    let result2 = broadcast(a2.clone(), shape2.clone());
    
    println!("Test 2 - Row vector broadcasting:");
    println!("Input array: {:?}", a2);
    println!("Shape: {:?}", shape2);
    println!("Result matrix: {}x{}", result2.rows(), result2.cols());
    println!("Data: {:?}", result2.data());
